class Buffer:
    def __init__(self, capacity):
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity <= 0:
            raise ValueError('capacity must be a positive integer')
        self.data = [None] * capacity
        self.read = 0
        self.size = 0

    def append(self, value):
        if self.size == len(self.data):
            self.data[self.read] = value
            self.read = (self.read + 1) % len(self.data)
        else:
            index = (self.read + self.size) % len(self.data)
            self.data[index] = value
            self.size += 1

    def pop(self):
        if self.size == 0:
            raise IndexError('pop from empty buffer')
        value = self.data[self.read]
        self.data[self.read] = None
        self.read = (self.read + 1) % len(self.data)
        self.size -= 1
        return value

    def snapshot(self):
        return [self.data[(self.read + i) % len(self.data)]
                for i in range(self.size)]
```

`size` distinguishes an empty slot from a stored `None`. Snapshots are new, shallow lists in oldest-first order.

